 void Update(){if(music){music.Volume=save.musicVolume;music.Duck=playing;}if(portrait&&Input.GetKeyDown(KeyCode.Return))NextStory();if(Input.GetKeyDown(KeyCode.F12))Capture(Path.Combine(Application.persistentDataPath,"screenshot.png"));if(Input.GetKeyDown(KeyCode.Space))GameKey(KeyCode.Space);if(Input.GetKeyDown(KeyCode.Escape)){if(modal)CloseModal();else if(inGame)ShowMenu();}if(Input.GetKeyDown(KeyCode.Z))GameKey(KeyCode.Z);if(Input.GetKeyDown(KeyCode.X))GameKey(KeyCode.X);if(Input.GetKeyDown(KeyCode.E))GameKey(KeyCode.E);if(boat){float bob=Mathf.Sin(Time.unscaledTime*1.2f)*3;boat.anchoredPosition=new Vector2(boatX,-350+bob);}if(!playing)return;elapsed+=Time.unscaledDeltaTime;if(elapsed<.7f)return;elapsed-=.7f;beat++;if(beat>=8){playing=false;beat=-1;playLabel.text="听 曲";UpdateSlots();if(!freeMode&&board.Matches(Content.Levels[level])&&ExplorationReady())Complete();else if(!freeMode)SetFeedback(PuzzleFeedback());else SetFeedback("这一圈结束了。可以继续修改，或保存短曲。");return;}Sound(board.cells[beat]);for(int i=0;i<8;i++)markers[i].color=i==beat?new Color(.65f,.28f,.21f,.22f):new Color(.3f,.35f,.3f,.04f);if(!board.cells[beat].Empty){StartCoroutine(Ripple(115+beat*119,460,tones[board.cells[beat].tone]));if(Content.Levels[level].chapter==0&&board.cells[beat].tone==Content.Levels[level].target[beat].tone&&board.cells[beat].rank==Content.Levels[level].target[beat].rank)boatX=Mathf.Min(930,boatX+(board.cells[beat].rank==2?55:25));}UpdateSlots();}
 void GameKey(KeyCode key){if(!inGame||modal)return;if(key==KeyCode.Space)Play();else if(key==KeyCode.Z)Undo();else if(key==KeyCode.X)SplitSelected();else if(key==KeyCode.E)OpenExploration();}
 IEnumerator VerifyButtonStyle(string dir){
  var b=page.GetComponentsInChildren<Button>().First();var f=b.GetComponent<InkButtonFeedback>();
  var p=new PointerEventData(EventSystem.current);var rt=b.GetComponent<RectTransform>();p.position=RectTransformUtility.WorldToScreenPoint(canvas.worldCamera,rt.TransformPoint(rt.rect.center));
  var hits=new System.Collections.Generic.List<RaycastResult>();EventSystem.current.RaycastAll(p,hits);
  if(hits.Select(h=>h.gameObject.GetComponentInParent<Button>()).FirstOrDefault(x=>x!=null)!=b)throw new Exception("Brush decoration blocked button");
  ExecuteEvents.Execute(b.gameObject,p,ExecuteEvents.pointerEnterHandler);yield return new WaitForSeconds(.2f);
  if(f.brush.Focus<.99f)throw new Exception("Button hover feedback missing");Capture(Path.Combine(dir,"button-hover.png"));
  ExecuteEvents.Execute(b.gameObject,p,ExecuteEvents.pointerDownHandler);yield return new WaitForSeconds(.12f);
  if(f.brush.Press<.99f)throw new Exception("Button press feedback missing");Capture(Path.Combine(dir,"button-pressed.png"));
  ExecuteEvents.Execute(b.gameObject,p,ExecuteEvents.pointerUpHandler);ExecuteEvents.Execute(b.gameObject,p,ExecuteEvents.pointerExitHandler);yield return new WaitForSeconds(.2f);
  if(f.brush.Focus>.01f||f.brush.Press>.01f)throw new Exception("Button exit feedback stuck");
  b.interactable=false;yield return null;ExecuteEvents.Execute(b.gameObject,p,ExecuteEvents.pointerClickHandler);
  if(inGame||!f.brush.Disabled)throw new Exception("Disabled button accepted input");Capture(Path.Combine(dir,"button-disabled.png"));b.interactable=true;yield return null;
 }
 IEnumerator Ripple(float x,float y,Color c){var p=page;var im=Panel(p,x,y,30,6,new Color(c.r,c.g,c.b,.3f));im.sprite=disc;float t=0;while(t<1.2f&&im){t+=Time.unscaledDeltaTime;im.rectTransform.sizeDelta=new Vector2(30+t*130,6+t*20);im.rectTransform.anchoredPosition=new Vector2(x-t*65,-y+t*10);im.color=new Color(c.r,c.g,c.b,.3f*(1-t/1.2f));yield return null;}if(im)Destroy(im.gameObject);}
 string PuzzleFeedback(){if(!ExplorationReady())return "还缺少归途的线索。点击“入景寻迹”，查看卷轴里的道具。";string reason;VerseRules.Check(board.cells,level,out reason);return reason;}
 void Complete(){solved=true;if(painting)painting.Grow((level+1)/9f);save.unlocked=Mathf.Max(save.unlocked,Mathf.Min(8,level+1));if(level==8)save.finished=true;Persist();StartCoroutine(FinishPainting(level));}
