 void OpenModal(string title,string body,string action,Action next){playing=false;Silence();if(modal)Destroy(modal.gameObject);var shade=Panel(page,0,0,1600,900,new Color(.08f,.18f,.15f,.55f));shade.raycastTarget=true;modal=shade.rectTransform;var sheet=Panel(modal,330,150,940,610,paper);InkEdge(sheet.transform,940,610,new Color(.25f,.3f,.25f,.2f));Label(modal,title,390,190,820,75,36,ink,TextAnchor.MiddleCenter);Label(modal,body,410,290,780,320,25,ink,TextAnchor.UpperLeft);Button(modal,action,600,650,400,58,next,true);}
