 void ShowStory(bool outro){playing=false;Silence();if(modal)CloseModal();storyPage=0;storyLines=outro?StoryText.Outro(Content.Levels[level].chapter):StoryText.Intro(Content.Levels[level].chapter);storyNext=outro?(Action)(()=>ShowPoem(Content.Levels[level].chapter,true)):(()=>OpenExploration());var shade=Panel(page,0,0,1600,900,new Color(.96f,.945f,.88f,1));shade.raycastTarget=true;modal=shade.rectTransform;Label(modal,Content.Chapters[Content.Levels[level].chapter],100,55,1000,65,37);Label(modal,outro?"墨色渐成 · 随词入境":"疏墨初起 · 随词入境",105,125,800,35,20,accent);var painted=Rect("Painting within story",modal,0,0,1600,900).gameObject.AddComponent<RawImage>();painted.raycastTarget=false;painted.transform.SetAsFirstSibling();painting=painted.gameObject.AddComponent<InkPainting>();painting.Initialize(level/9f);if(outro)painting.Grow((level+1)/9f);var dialogueSheet=Panel(modal,760,530,720,205,paper);InkEdge(dialogueSheet.transform,720,205,new Color(.25f,.3f,.25f,.2f));Label(modal,"画 中 人",790,555,600,45,28,red);var words=Label(modal,"",790,610,640,105,25);portrait=modal.gameObject.AddComponent<PortraitMotion>();portrait.dialogue=words;portrait.reduceMotion=true;portrait.SetLine(storyLines[0]);Button(modal,"继续  ↵",1010,730,250,60,NextStory,true);Button(modal,"略过此段",1255,805,220,50,SkipStory);Button(modal,"墨染动态",790,805,220,50,()=>{storyReduced=!storyReduced;if(painting)painting.Motion=!storyReduced;});}
 public void NextStory(){if(!portrait)return;if(portrait.Typing){portrait.FinishLine();return;}storyPage++;if(storyPage>=storyLines.Length){SkipStory();return;}portrait.SetLine(storyLines[storyPage]);}
 public void SkipStory(){if(!portrait)return;var next=storyNext;storyNext=null;CloseModal();if(next!=null)next();}
 void ShowPoem(int c,bool advancing){string name=c==2?"一剪梅":"如梦令";OpenModal(name+" · 李清照",Content.Poems[c]+"\n\n"+Content.Notes[c],advancing?(level==8?"写下自己的声音":"翻开下一页"):"收起词笺",()=>{CloseModal();if(advancing){if(level==8)StartFree();else LoadLevel(level+1);}});}
 void ShowAnthology(){OpenModal("词 笺","每完成一章，收下这一页词。\n\n诗词文本与可查看的文化说明随旅程解锁。\n游戏音石机关为词意改编；五音旋律为原创，\n不作为宋代原曲或真实传记的复原。","返回",CloseModal);for(int c=0;c<3;c++){int ch=c;bool unlocked=save.unlocked>c*3+2||(c==2&&save.finished);var b=Button(modal,Content.Chapters[c]+(unlocked?"":" · 未读"),410+c*270,555,245,52,()=>{if(unlocked)ShowPoem(ch,false);});b.interactable=unlocked;}}
 void ShowChapters(){OpenModal("沿 词 入 境","三章九景 · 每一景都可以重新回听\n\n已走过的路可以随时重访。选择后从该景初始音石开始。","返回",CloseModal);for(int i=0;i<9;i++){int n=i;var b=Button(modal,(i+1)+" "+Content.Levels[i].title.Substring(4),415+i%3*268,360+i/3*80,245,60,()=>{CloseModal();LoadLevel(n);});b.interactable=i<=save.unlocked;}}
 void ShowAbout(){OpenModal("关于 · 词境","李清照词意改编 / 五音合成与声音解谜\n美术：AI 生成水墨背景；场景反馈与界面为原创。\n字体：马善政楷书（SIL Open Font License）。\n声音：VSCO 2 CE 竖琴、长笛采样；原创编排。\n\n操作：点选或拖动；空格试听；Z 撤销；Esc 返回。\n存档保存在本机，可关闭后继续旅程。\n本作场景、机关与章节顺序均为艺术改编。","返回",CloseModal);}
 void StartFree(){inGame=true;freeMode=true;solved=false;level=save.finished?8:Mathf.Clamp(save.level,0,8);board=new Board();if(save.composition!=null&&save.composition.Length==16)board.Restore(save.composition);else{for(int i=0;i<8;i++)board.cells[i+8]=new Stone(i%5);}hint=0;DrawGame();SetFeedback("自由谱曲：音石可移动、合成与拆分。点“保存短曲”留下当前版本。");}
 public void Capture(string path){Canvas.ForceUpdateCanvases();var camera=Camera.main;var old=camera.targetTexture;var rt=RenderTexture.GetTemporary(1600,900,24);camera.targetTexture=rt;camera.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(1600,900,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1600,900),0,0);t.Apply();File.WriteAllBytes(path,t.EncodeToPNG());Destroy(t);camera.targetTexture=old;RenderTexture.active=previous;RenderTexture.ReleaseTemporary(rt);}
 void ClickSlotForTest(int index){Canvas.ForceUpdateCanvases();var pos=RectTransformUtility.WorldToScreenPoint(canvas.worldCamera,slotImages[index].rectTransform.TransformPoint(slotImages[index].rectTransform.rect.center));var e=new PointerEventData(EventSystem.current){position=pos};var hits=new System.Collections.Generic.List<RaycastResult>();EventSystem.current.RaycastAll(e,hits);var hit=hits.Select(h=>h.gameObject.GetComponentInParent<SlotInput>()).FirstOrDefault(h=>h!=null);if(hit==null||hit.index!=index)throw new Exception("UI raycast missed slot "+index);ExecuteEvents.Execute(hit.gameObject,e,ExecuteEvents.pointerClickHandler);}
 IEnumerator SelfTest(){var dir=Path.Combine(Application.dataPath,"../Validation");Directory.CreateDirectory(dir);yield return new WaitForSeconds(1);Capture(Path.Combine(dir,"00-menu.png"));yield return VerifyButtonStyle(dir);for(int stage=0;stage<3;stage++){painting.Snap(stage*.5f);Capture(Path.Combine(dir,"painting-stage-"+stage+".png"));}painting.Snap(.3f);painting.Grow(.5f);float before=painting.Current;Capture(Path.Combine(dir,"ink-before.png"));yield return new WaitForSeconds(.65f);Capture(Path.Combine(dir,"ink-after.png"));if(painting.Current<=before)throw new Exception("Ink growth did not advance");yield return new WaitForSeconds(.5f);int passed=0;for(int n=0;n<9;n++){save.evidence[n]=0;LoadLevel(n);if(ExplorationReady())throw new Exception("Unobserved clues accepted");yield return new WaitForSeconds(.35f);if(portrait){Capture(Path.Combine(dir,"story-"+n+".png"));NextStory();NextStory();SkipStory();}if(exploration){yield return null;for(int prop=0;prop<3;prop++){ExploreArtworkForTest(prop);yield return null;yield return ExploreHoverForTest(prop,dir,n);yield return null;}if(!ExplorationReady())throw new Exception("Clues did not unlock puzzle");Capture(Path.Combine(dir,"explore-"+n+".png"));CloseModal();}yield return null;var l=Content.Levels[n];int mass=board.Mass; if(n==0){Canvas.ForceUpdateCanvases();var src=RectTransformUtility.WorldToScreenPoint(canvas.worldCamera,slotImages[8].rectTransform.TransformPoint(slotImages[8].rectTransform.rect.center));var dst=RectTransformUtility.WorldToScreenPoint(canvas.worldCamera,slotImages[0].rectTransform.TransformPoint(slotImages[0].rectTransform.rect.center));BeginDrag(8,src);DragAt(dst);EndDrag(new PointerEventData(EventSystem.current){position=dst});if(board.cells[0].Empty||!board.cells[8].Empty)throw new Exception("Drag move failed");Undo();} // Drive the same selection path used by clicks, including every required merge.
 for(int i=0;i<8;i++){var t=l.target[i];if(t.Empty)continue;for(int count=0;count<t.Mass;count++){int from=Array.FindIndex(board.cells,8,8,s=>!s.Empty&&s.tone==t.tone);if(from<0)throw new Exception("Missing source stone");ClickSlotForTest(from);ClickSlotForTest(i);}}
 if(board.Mass!=mass||!board.Matches(l))throw new Exception("Puzzle failed "+n);if(n==1){selected=0;GameKey(KeyCode.X);GameKey(KeyCode.Z);if(!board.Matches(l))throw new Exception("Split undo failed");}
 Persist();var read=JsonUtility.FromJson<SaveData>(File.ReadAllText(savePath));if(read.cells.Length!=16||read.level!=n||read.evidence[n]!=7)throw new Exception("Save reload failed");if(n==0){GameKey(KeyCode.E);if(!exploration)throw new Exception("Explore shortcut failed");CloseModal();}GameKey(KeyCode.Space);if(!playing)throw new Exception("Play shortcut failed");yield return new WaitForSeconds(1.3f);Capture(Path.Combine(dir,"level-"+n+".png"));yield return new WaitForSeconds(7.3f);if(!solved)throw new Exception("Runtime completion failed "+n);passed++;if(n%3==2){Capture(Path.Combine(dir,"outro-"+n+".png"));SkipStory();Capture(Path.Combine(dir,"poem-"+n+".png"));}CloseModal();}
 StartFree();yield return new WaitForSeconds(.5f);save.composition=(Stone[])board.cells.Clone();Persist();if(!music.Active)throw new Exception("Background score not playing");if(runtimeErrors>0)throw new Exception("Runtime errors were recorded: "+runtimeErrors);File.WriteAllText(Path.Combine(dir,"runtime-results.json"),"{\"passedLevels\":"+passed+",\"saveRoundTrips\":9,\"splitUndo\":true,\"completed\":true}");Debug.Log("CIJING_RUNTIME_PASS 9 levels, save, split undo");yield return new WaitForSeconds(1);Application.Quit();}
